from pathlib import Path
from html import escape
OUT=Path(__file__).resolve().parent / 'figures'
INK='#18334c';MUT='#586d80';BLUE='#2376c5';GREEN='#17816c';ORANGE='#c36b24';PURPLE='#7750ad'
def txt(x,y,s,size=22,color=INK,bold=False):return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}" font-weight="{700 if bold else 400}">{escape(s)}</text>'
def rect(x,y,w,h,fill='#ffffff',stroke='#d9e3ec',rx=16):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="{stroke}" rx="{rx}"/>'
def line(x,y,X,Y,c=BLUE,dash=False):return f'<path d="M{x},{y} L{X},{Y}" fill="none" stroke="{c}" stroke-width="3" marker-end="url(#{c[1:]})" '+('stroke-dasharray="9 6"' if dash else '')+'/>'
def path(d,c=BLUE,dash=False):return f'<path d="{d}" fill="none" stroke="{c}" stroke-width="3" marker-end="url(#{c[1:]})" '+('stroke-dasharray="9 6"' if dash else '')+'/>'
def box(x,y,w,h,title,lines,c=BLUE):
 s=rect(x,y,w,h,'#fff',c)+txt(x+18,y+32,title,23,c,True)
 for i,t in enumerate(lines):s+=txt(x+18,y+65+29*i,t,19)
 return s
def panel(y,title,h):return rect(28,y,1344,h,'#f6f9fc')+txt(50,y+34,title,24,INK,True)
def save(slug,title,sub,s,h=1040):
 defs=''.join(f'<marker id="{c[1:]}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0,0 L10,5 L0,10Z" fill="{c}"/></marker>' for c in [BLUE,GREEN,ORANGE,PURPLE])
 doc=f'<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="{h}" viewBox="0 0 1400 {h}" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(sub)}</desc><defs>{defs}</defs><g font-family="Microsoft YaHei, Noto Sans CJK SC, Arial, sans-serif">'+rect(0,0,1400,h,'#fff','#fff',0)+txt(36,50,title,32,INK,True)+txt(36,87,sub,19,MUT)+s+txt(36,h-23,'原创阅读示意 · 非实验测量 / 非逐算子实现 · 配套正文解释所有假设与缺失细节',17,MUT)+'</g></svg>'
 (OUT/f'{slug}-method-v2.svg').write_text(doc,encoding='utf-8')
