s+=box(52,451,585,175,'姿态通路：通道缩放后加到下采样块',['α_p = α_p^base + α_p^res','教学：base=.7、res=.1 → α_p=.8','空间维广播，各尺度通道数需匹配','不能把一个不匹配的向量直接乘全部层'],PURPLE)
s+=box(697,451,639,175,'外观通路：token缩放后进入cross-attention',['α_a = 1−α_p^base + α_a^res','教学：res=.2 → α_a=.5；两者总和=1.3','K/V变化也会改变softmax，不是输出线性比例','base互补，不代表最终权重相加永远等于1'],GREEN)
s+=panel(655,'03  PIAE：patch特征分解与全局CLS分别提供信息',255)
s+=box(52,721,380,165,'同身份参考 → CLIP patches',['N×H_p×W_p×D → Q×D矩阵','SVD主方向只表示强变化','强变化未必只有姿态','rank与是否中心化需核对'],BLUE)+line(432,800,484,800)
s+=box(494,721,395,165,'标准投影对照，不冒充原式',['若 B 为 D×r正交基','E_perp = E − EBBᵀ','E=(2,3)、B=(1,0)ᵀ → (0,3)','原式4的转置与P_proj定义待核'],ORANGE)+line(889,800,941,800)
s+=box(951,721,385,165,'空间聚合 + CLIP全局CLS',['局部细节token与全局语义拼接','得到外观条件 F_a','正交不证明语义 / 统计独立','单参考也可有多个空间patch'],GREEN)
s+=panel(935,'04  每个去噪步重新调制；固定参考不等于固定控制强度',235)
s+=txt(55,1003,'参考 / 姿态特征 → 当前 z_t 与时间 → 预测权重 → U-Net去噪 → 下一步 → VAE图像。',22,INK,True)
s+=txt(55,1049,'同一latent时间下内容可不同；通道平均权重曲线也不能当逐因素因果贡献。',22,PURPLE)
s+=txt(55,1095,'教学系数和二维投影不是真实手部生成结果；未训练模型、未下载权重或生成图像。',21,MUT)
save('tcca-hand','TCCA ｜按去噪状态调整姿态与外观，不让固定日程包办','依据原文 Fig.3、式2–4、§3，PDF 4–6；权重、广播与投影例为独立教学内容。',s,1230)

# ORCA: accepted state and candidate state are deliberately separate.
s=panel(115,'01  已接受的状态是下一轮起点：目标、物体、清单与历史一起保留',245)
s+=box(52,179,380,165,'Observe：更新证据',['输入已接受片段的抽帧','场景对象 + 子目标清单 + 历史','教学：大盆有土，幼苗仍在小盆','belief为结构化记忆，非概率表'],BLUE)+line(432,258,484,258)
s+=box(494,179,395,165,'Think / System 2：双目标',['g：把根团从小盆取出','预期：手托根团，根团已离盆','动作命令与预计状态分别输出','本轮目标依据最新进度选择'],PURPLE)+line(889,258,941,258)
s+=box(951,179,385,165,'Act / System 1：提示落地',['读当前图像、状态与双目标','补对象、手、位置、动作次序','输出面向I2V模型的详细caption','两System是同VLM的不同分工'],GREEN)
s+=panel(385,'02  候选区：每次生成都可能失败，不能直接改写已接受状态',245)
s+=box(52,451,585,165,'生成候选视频 → 抽帧 → Reflect',['G(原已接受观测, 当前caption)','比较：候选画面 / 子目标 / 预计结果','教学候选A：手动了，根团仍未离盆','核验可漏检、误拒绝；抽帧也可能漏掉异常'],BLUE)
s+=box(697,451,639,165,'拒绝分支：诊断可以使用，场景进展不提交',['失败分析 → 修订caption → 从同一起点重新生成','不是接着失败候选的末帧继续下一子目标','预算耗尽：重规划，不自动宣称目标已完成','本轮尝试增加，最终视频段数暂不增加'],ORANGE)
s+=panel(655,'03  接受分支：候选成为正式片段，下一轮才更新进度',215)
s+=txt(55,723,'教学候选B：根团确已离盆 → accept → 追加视频 → Observe确认 → 计划放入大盆。',23,GREEN,True)
s+=txt(55,771,'视频制作能丢弃失败候选；不能据此认为现实机器人动作可以通过删视频撤销。',22,INK)
s+=txt(55,819,'原文算法最后一次重试可能未核验就退出；教学循环保证每个候选先检查，再决定退出。',21,ORANGE)
s+=panel(895,'04  预算与指标分开算：以下数字全是教学构造，不是ORCA实验',280)
s+=box(52,961,585,185,'生成调用 ≠ 最终视频长度',['4个子目标，每步最多2次额外重试','无额外重规划时：至多4×3=12次生成','独立成功率p=.5、最多3次：成功概率.875','期望尝试1+.5+.25=1.75；真实尝试未必独立'],PURPLE)
s+=box(697,961,639,185,'TSR ≠ 整任务成功率',['两个任务完成2/4和3/3','逐任务比例均值：(1/2+1)/2=75%','整任务全部完成：1/2=50%','合并子目标：5/7≈71.4%，又是另一个指标'],BLUE)
s+=txt(55,1215,'依据Fig.2、式1–7、Algorithm 1，PDF3–6；未调用VLM、未生成视频、未复现实验。',21,MUT)
save('orca-video-avatars','ORCA ｜先验证候选，再让世界状态向前一步','原创中文教学图：将已接受轨迹、候选生成与失败诊断分开，避免计划替代事实。',s,1290)


# D2C: offline data selection versus trainable student paths.
s=panel(115,'01  Select：先核对分数方向，再说明固定预算怎样取排名',250)
s+=box(52,179,585,165,'评分模型读取真实图像、类别、时间与噪声',['去噪误差用于估计学习难度','原式7印负MSE，但文字说高分更难','教学误差 .1 / .9 → 取负 −.1 / −.9','排序方向会反转，必须核对实际实现'],ORANGE)
s+=box(697,179,639,165,'每类排序 + 间隔取样',['教学：12张图，每类预算3张','k=1：索引0,1,2；k=3：0,3,6；k=5：0,5,10','固定取3张才体现覆盖区域变化','遍历全列表的集合式还需截断 / 越界规则'],BLUE)
s+=panel(390,'02  Attach：离线缓存两种信息，各自回答不同问题',250)
s+=box(52,456,585,165,'类别文本：类间语义',['类别提示 → T5 → 文本token + mask','训练时：mask → Conv1d → 残差MLP','加可学习类别嵌入 → 条件表示','卷积 / 汇聚 / 投影须满足相加维度'],PURPLE)
s+=box(697,456,639,165,'逐图视觉：类内结构',['选中真实图 → DINOv2 → patch表征','缓存前h个token：h须不大于已有token数','截取不是自动空间对齐，也不是重要性排序','教师缓存固定，作为学生的监督目标'],GREEN)
s+=panel(665,'03  训练：任务预测与中间特征对齐，共同更新目标扩散模型',255)
s+=box(52,731,380,165,'学生前向',['图像 → latent → 随机加噪','输入时间、类别与文本条件','输出噪声 / 对应骨干训练目标','同时读取指定层学生token'],BLUE)+line(432,810,484,810)
s+=box(494,731,395,165,'视觉辅助目标',['投影 φ：学生维度 → 教师维度','负余弦平均：−mean cos(φ(h),v)','梯度经φ回到学生','缓存v不随训练更新'],GREEN)+line(889,810,941,810)
s+=box(951,731,385,165,'合并损失',['L_total = L_diff + .5 L_proj','教学：(3,4)与(0,1)余弦=.8','L_diff=.6 → 总损失=.2','视觉项可为负，不是错误'],PURPLE)
s+=panel(945,'04  训练数据比例、推理接口、总成本要分开理解',245)
s+=txt(55,1013,'采样：噪声 + 类别 / 文本条件 → 生成图；视觉缓存用于训练对齐，不是必需参考图。',22,INK,True)
s+=txt(55,1060,'0.8%是目标训练子集：评分会看原数据，预训练知识与表征存储并未消失。',22,ORANGE)
s+=txt(55,1107,'作者Table 6：预训练评分器2.1h + 训练7.4h = 9.5h；自训评分器合计35.5h。',22,BLUE)
s+=txt(55,1154,'本文索引、向量与损失为教学计算；未训练模型、未生成图像、未下载训练数据。',21,MUT)
save('d2c','D²C ｜挑选真实图像，再把语义与视觉知识附加给学生','依据Fig.2/4、式5–12与Table 6，PDF3–8；明确离线缓存、训练梯度与公式核对边界。',s,1250)


# HistoSelect: group budgets and patch ranking are different operations.
s=panel(115,'01  先按组织分组，再让问题决定保留预算',245)
s+=box(52,179,380,165,'CONCH图像 / 文本空间',['224×224图块 → x_i','专家组织提示 → t_j','最大余弦指定组织类别','patch标签不是像素级真值'],BLUE)+line(432,258,484,258)
s+=box(494,179,395,165,'组原型 + 问题 → 比例',['g_j = 组内特征平均','[g_j;q] → 两层网络 → sigmoid','r_j是每组比例，不是softmax','均值可能稀释少量特殊结构'],PURPLE)+line(889,258,941,258)
s+=box(951,179,385,165,'组内分数 → top-k',['[x_i;q] → 两层网络 → s_i','k_j = ceil(r_j N_j)','每组分别按s_i选前k_j','不是独立Bernoulli随机抽样'],GREEN)
