# ARCA-GS: resolution adaptation and feature compression are separate paths.
s=panel(115,'01  同一锚点随渲染尺寸改变特征，再解码高斯属性',245)
s+=box(52,179,585,165,'位置与尺寸 → FiLM',['PE(x_v, ξ) → MLP → γ, β','f_hat = (1+γ) ⊙ f + β','教学 f=(2,−1), γ=(.5,0), β=(−1,.2)','调制结果 (2,−.8)，不是把最终图像resize'],BLUE)
s+=box(697,179,639,165,'属性解码 → 当前相机投影',['同一锚点可生成多个高斯','预测几何、颜色和透明度等属性','投影协方差Σ₂D必须使用像素坐标','透明度筛选阈值与覆盖门控分开处理'],PURPLE)
s+=panel(385,'02  Pixel Coverage Gate：面积是平方量，门控是连续量',245)
s+=box(52,451,585,165,'椭圆覆盖面积',['A = πρ² sqrt(det Σ₂D)，作者ρ=1','固定几何时，宽高减半 → 面积变1/4','FiLM也改几何时需重新投影计算','面积单位不应混成世界坐标长度'],GREEN)
s+=box(697,451,639,165,'有效透明度 α_eff = α sigmoid(κ(A−η))',['A=η时门控=.5，不是完全保留','局部梯度 α κ g(1−g)，两端会饱和','alpha合成有前后遮挡耦合','仅推理加门控不保证画质不变'],ORANGE)
s+=panel(655,'03  代理特征 + 几何条件 → 残差 → 叶特征',245)
s+=box(52,721,380,165,'约30%代理保存特征',['网格内密度感知随机选择','其余叶保留恢复所需元数据','代理特征先适配目标尺寸','不是删除70%的全部几何'],BLUE)+line(432,800,484,800)
s+=box(494,721,395,165,'预测器输入局部关系',['代理特征 + PE(距离,方向)','原式方向 x_proxy−x_leaf','文字方向描述与公式相反','零距离需额外数值处理'],ORANGE)+line(889,800,941,800)
s+=box(951,721,385,165,'预测叶 = 代理 + 残差',['教学 (1,2)+(.2,−.3)=(1.2,1.7)','同维特征相加，再解码属性','特征差不是三维位移','省存储，同时增加预测计算'],GREEN)
s+=panel(925,'04  训练只替换部分叶；推理压缩与训练替换比例不同',265)
s+=txt(55,993,'教学100锚点：30代理 + 70叶；一步替换20%的叶，即14预测叶 + 56原叶 + 30代理。',22,INK,True)
s+=txt(55,1040,'第一阶段用图像损失；增长剪枝结束后再延迟1k步启动预测器，与特征重建项联合优化。',21,PURPLE)
s+=txt(55,1087,'重建 = MSE + .1(1−cos)；λ_recon在20k前.1、之后.01，作者总训练30k步。',22,BLUE)
s+=txt(55,1134,'存特征锚点数 ≠ 渲染高斯数 ≠ FPS；数值例仅用于解释，未渲染场景或复现实验。',21,MUT)
save('arca-gs','ARCA-GS ｜分辨率适配、像素门控与代理压缩怎样连接','依据Fig.2、式5–14与实施细节，PDF3–7；教学特征与数量不代表作者实验。',s,1250)


# A3: heterogeneous task rewards are activated selectively.
s=panel(115,'01  数据先有人工目标，再由模型生成解释并抽样审核',245)
s+=box(52,179,585,165,'人工标签 / 框 / 主观分数',['30K广告图 → 120K指令响应对','批次质量阈值不是模型性能','按规则分二元、定位、评分任务','广告属性分数不是购买转化率'],BLUE)
s+=box(697,179,639,165,'模型解释与专家抽样',['模型依据规则和答案生成解释','单条抽样接受需5位专家至少3票','评估子集接受率需稳定超过85%','不等于所有解释都由专家逐条书写'],PURPLE)
s+=panel(385,'02  SFT学格式与任务，GRPO按当前规则选择有效奖励',245)
s+=box(52,451,585,165,'所有样本：格式 + 去重复',['格式有效 → R_format','句子与n-gram去重比例平均 → R_nonrep','能解析、少重复，不保证事实或逻辑正确','短文本与零分母需要实现规则'],BLUE)
s+=box(697,451,639,165,'仅适用任务：准确 / 工具 / 框 / 分数',['二元：标签匹配；三类规则：工具调用且引用','图标：一对一匹配，IoU严格大于.5','主观：exp(−误差²/(2σ²))，σ=1.237','不适用奖励不应当作0参与平均'],GREEN)
