s+=box(52,721,380,165,'高斯评分奖励',['误差0 → 1','误差1 → 约.721','误差2 → 约.271','不是直接优化跨样本SRCC'],PURPLE)
s+=box(494,721,395,165,'有效奖励加权平均',['教学等权：1、.8、1','总分2.8/3≈.933','只用当前任务的有效项','格式项未明示为乘法硬门控'],BLUE)
s+=box(951,721,385,165,'GRPO教学优势',['候选奖励 .2、.5、.8','组均值 .5，总体标准差≈.245','标准化约−1.225、0、1.225','组大小与完整优化细节需核对'],GREEN)
