s+=box(52,179,380,165,'原图 → 固定图像编码器',['原特征 E_ori','Enc(E_ori,P) → 替代表征','密钥条件进入cross-attention','每个编码接口分别训练网络'],BLUE)+line(432,258,484,258)
s+=box(494,179,395,165,'正确密钥恢复',['Enc输出应远离原特征','Dec(E_enc,P_correct)应接近原特征','正确恢复损失权重作者设5','余弦接近不代表逐比特可逆'],GREEN)+line(889,258,941,258)
s+=box(951,179,385,165,'错误密钥与多样性',['错误密钥解码应远离原特征','跨样本 / 密钥输出不要塌缩','成对项1/2只消除双计数','batch变化也改变损失尺度'],ORANGE)
