# HybriDiff: exact CFG dependency versus approximate schedule.
s=panel(115,'01  同一步、同一张潜图：两个前向之后必须汇合',250)
s+=box(52,180,300,165,'相同x_t / 不同条件',['GPU A：f(x_t,t,c) → ε_c','GPU B：f(x_t,t,空) → ε_u','两个输出都与潜变量同形','处理整图，不是左右切图'],BLUE)
s+=line(352,255,420,255)
s+=box(435,180,435,165,'引导组合 → 采样器更新',['本文：ε_cfg = ε_c + w(ε_c−ε_u)','另一常见记号：ε_u+s(ε_c−ε_u)','二者只有s=1+w时对应','汇合预测后才得到下一步潜变量'],GREEN)
s+=line(870,255,930,255)
s+=box(945,180,390,165,'教学：ε_c=2，ε_u=1.5',['w=3 → 2+3×.5=3.5','若另一记号也填3 → 3.0','仅参数名相似不代表配置相同','本方法不反向更新模型权重'],PURPLE)
s+=panel(390,'02  执行步j递增；不要与递减的噪声时间t混用',270)
s+=box(52,455,380,155,'前段：条件划分',['保留条件 / 无条件路径','收集分支差异指标','计算窗口斜率与进入条件'],BLUE)+line(432,528,478,528)
s+=box(493,455,395,155,'中段：额外流水并行',['跨路径交换与跨步交错','引入近似计算 / 依赖变化','逐层缓存规格需附录C/F'],ORANGE)+line(888,528,932,528)
s+=box(947,455,390,155,'末段：恢复条件划分',['继续条件细节精修','不是改成一个全连接层','结束点是进入后固定k步'],GREEN)
s+=txt(70,640,'教学：j₁=8，k=10 → j₂=18；不是在线检测每幅图下一次真实分歧。',22,PURPLE)
s+=panel(685,'03  相对差异与近似误差：两个算例各自回答不同问题',245)
s+=box(52,750,595,165,'M：分支预测差异的相对尺度',['ε_u=(1,−1)，ε_c=(1.1,−.9)','差的L1=.2；基准L1=2 → M=.1','不是图像误差10%，也不是语义准确率','期望之比 ≠ 比值的期望'],BLUE)
s+=box(697,750,640,165,'CFG会放大不对称预测误差',['误差传播：(1+w)d_c − w d_u','w=3，d_c=.1，d_u=0 → 偏差.4','后续采样把误差带入新的潜变量','低M不是最终图像误差上界'],ORANGE)
s+=panel(955,'04  调度与性能声明的边界',240)
s+=txt(55,1022,'斜率符号须匹配时间方向；τ_cap来自全局最低点，纯在线获取方式主文未明。',22,INK,True)
