# 3PT: cached CAD context and iterative geometric refinement.
s=panel(115,'01  CAD编码两种用途：先验条件不等于姿态候选',245)
s+=box(52,179,385,165,'12个固定视角：Prior',['渲染 → 编码 / 池化 / 拼接','与真实图像token早融合','按目标CAD生成物体相关假设','每个CAD分别前向再NMS'],BLUE)
