s+=box(52,179,385,165,'冻结DINOv3 → 空间特征',['x_prev与x_now：P×D','编码器读取两帧和汇聚token','z=g(x_prev,x_now,z_init)：D维','不是显式差分后求平均'],BLUE)+line(437,255,483,255)
