s+=box(697,451,640,165,'教学BoM：真值(0,0)',['A=(.1,.1)，B=(1,1)','标准smooth L1转折1：损失.01与1','选整个A；不是每维分别拼最佳候选','真实实现归约需核查；不拟合未来概率'],PURPLE)
s+=panel(655,'03  每条未来独立滚动；空间解码仍按时间顺序',265)
s+=box(52,720,385,165,'分支A：自己的历史',['Z → z_A1 → z_A2 → z_A3','每步重新采样query','每步追加本分支预测delta','不借用分支B或真实未来'],BLUE)+line(437,800,483,800)
s+=box(498,720,395,165,'顺序恢复空间特征',['真实x_t + z_A1 → x_A1','预测x_A1 + z_A2 → x_A2','预测x_A2 + z_A3 → x_A3','后步不能偷用真实x_(t+1)'],GREEN)+line(893,800,939,800)
s+=box(954,720,380,165,'固定下游任务头',['空间特征 → 分割 / 深度','世界模型并非直接输出像素视频','中期三步，不是任意未来一步完成','预测与解码误差都可能累积'],ORANGE)
