s+=box(697,451,640,165,'跨尺度与重建不要混为一谈',['L_cos除以g，未再除以两种尺度关系','重建条件是带波浪F；目标是不带波浪F','L_rec按中心平均，特征维内部平方求和','推理用L2距离，不是训练平方距离'],ORANGE)
s+=panel(655,'03  几何偏置先加logits，再softmax',245)
s+=box(52,721,595,165,'语义项 + β B_geo → 权重',['教学语义logits=(0,0)','偏置=(0,ln3)，β=1','权重从(.5,.5)变成(.25,.75)','不是输出后乘二值mask'],GREEN)
