s+=panel(925,'04  评分顺序：单实例归一化 → 一维滤波 → 最大值',280)
s+=txt(55,992,'教学A=(1,2,3)，B=(10,20,30)：各自min–max后都为(0,.5,1)。',23,INK,True)
s+=txt(55,1040,'滤波前最大值都为1；绝对误差尺度消失，滤波后依赖局部形状和边界规则。',22,ORANGE)
