# AcTTA: function curves calculated from equation 1 with illustrative values.
import math
s=panel(115,'01  真实公式曲线：蓝色原ReLU，橙色为教学参数下的g(x)',350)
s+=f'<path d="M90 390 H560 M325 420 V190" fill="none" stroke="{MUT}" stroke-width="2"/>'
for xv in [-2,-1,0,1,2]:s+=txt(325+xv*90-8,440,str(xv),17,MUT)
for c,fun in [(BLUE,lambda x:max(x,0)),(ORANGE,lambda x:max(x-.5,0)+(.2+(-.1-.2)/(1+math.exp(-(x-.5))))*(x-.5))]:
 points=[(325+x*90,390-fun(x)*70) for x in [-2.5+i*.025 for i in range(201)]]
 s+=f'<polyline points="'+ ' '.join(f'{x:.2f},{y:.2f}' for x,y in points)+f'" fill="none" stroke="{c}" stroke-width="3"/>'
s+=txt(650,195,'β=1，c=.5，λ_neg=.2，λ_pos=−.1',23,INK,True)
s+=txt(650,245,'u=x−c；s=σ(βu)；a=.2(1−s)−.1s',22)
s+=txt(650,295,'x=−.5 → g≈−.1193；x=1.5 → g≈.9807',21,ORANGE)
s+=txt(650,345,'原函数 + 输入相关线性残差，不只是平移。',22,BLUE)
s+=txt(650,395,'图为公式计算，不是作者训练出的参数。',21,MUT)
s+=panel(490,'02  完整导数：a(u)不能直接当作g的斜率',240)
s+=txt(55,558,"g′(x)=φ′(u)+a(u)+uβ(λ_pos−λ_neg)s(1−s)",26,BLUE,True)
s+=txt(55,607,'教学u=1：a≈−.0193，但完整导数≈.9217；正侧还有基础ReLU斜率1。',22,ORANGE)
s+=txt(55,655,'参数梯度：∂g/∂λ_pos=us；∂g/∂λ_neg=u(1−s)；∂g/∂c=−g′。',22,PURPLE)
s+=txt(55,700,'ReLU在u=0不可经典求导；实现使用框架次梯度，不能说所有位置都光滑。',21,MUT)
s+=panel(755,'03  零初始化：输入梯度与参数梯度分开',200)
s+=txt(55,823,'c=λ_pos=λ_neg=0 → g=原激活；对ReLU负输入x=−1，g′=0。',23,INK,True)
s+=txt(55,872,'但β=1时两个λ参数梯度约−.269、−.731；有上游梯度时仍可能更新。',22,GREEN)
s+=txt(55,920,'不能说“初始化时所有负侧输入梯度立即非零”；也不能保证适应后始终单调。',21,ORANGE)
s+=panel(980,'04  测试更新与代价',225)
s+=txt(55,1047,'无标签batch → 概率 / 原TTA损失 → 反传到允许参数 → 更新 → 按协议预测与重置。',21,INK,True)
s+=txt(55,1095,'CNN常只适应激活；ViT还更新LN仿射。BN仿射冻结不自动说明统计冻结。',21,PURPLE)
s+=txt(55,1143,'少量新增参数仍有反传开销；低熵可以自信地错，需同时比较冻结源模型。',22,ORANGE)
