s+=box(52,179,385,165,'运动学边界先确定',['轨迹偏离线性外推 → Atom边界','段内max-pool初始化query','该段帧token作K/V，聚成一个token','自注意力限同段；阈值需补充材料'],BLUE)+line(437,255,483,255)
