s+=box(697,451,640,165,'EMA更新目标，不是梯度直接更新目标',['在线参数通过预测损失更新','目标参数跟随在线参数的移动平均','预训练缺失补全不自动等于因果预测','未来任务不能读真实未来段长'],BLUE)
s+=panel(655,'03  均值只覆盖被遮挡集合：局部与全局控制不同误差',265)
s+=box(52,721,385,170,'目标(1,3)，预测(2,4)',['目标均值2，预测均值3','局部都为(−1,1)','局部误差0，全局仍有偏差','不是所有误差都被局部项约束'],GREEN)
s+=box(498,721,395,170,'目标(1,3)，预测(0,4)',['两边均值都是2','局部为(−1,1)与(−2,2)','全局误差0，局部仍不同','比值分母为0需稳定规则'],ORANGE)
