s+=box(52,179,385,165,'规范高斯 → 时刻t几何',['中心3维，协方差3×3','HexPlane六平面编码时空','三MLP头更新位置 / 旋转 / 尺度','不依赖曝光元数据≠不需要位姿'],BLUE)+line(437,255,483,255)
s+=box(498,179,395,165,'照明与反射率分开',['球谐描述方向依赖照明','OCD-Net给每基时间增益','高斯反射率RGB不显式随时间变','屏幕R图仍受投影 / 遮挡影响'],GREEN)+line(893,255,939,255)
s+=box(954,179,380,165,'按深度排序与透射率混合',['T_i=前面所有(1−α)的乘积','L图H×W；R图H×W×3','两图分别混合，再I=L⊙R','不是逐高斯先乘颜色再混合'],PURPLE)
