s+=box(52,721,595,165,'每高斯b1,b2 → 两张BAF图',['同一光栅权重投影为Bhat1/Bhat2','H×W×2 → BAFE-Net → B1/B2','暗图 = L的B2次幂 ⊙ R的B1次幂','两个幂结果之间才是逐元素乘'],GREEN)
s+=box(697,721,640,165,'教学L=.8，R=.6，B2=2，B1=1',['明亮图=.48；退化后=.384','0<a<1时指数>1变暗，<1变亮','多个L/R/B组合可解释相同暗图','所以数据项之外必须明确正则偏好'],PURPLE)
