s+=box(52,179,385,165,'N×D编码特征 → N×N相似度',['S为两两余弦，不是空间距离','n_i统计S_ij > θ，含自身','先按n_i降序排列候选','循环删邻居，不重新计算度数'],BLUE)+line(437,255,483,255)
