s+=rect(697,569,640,56,'#edf8f1')+txt(718,606,'最终簇B：45°、60° → 中心60°',24,GREEN,True)
s+=panel(675,'03  聚合顺序：先给value输入加位置，再投影与簇内加权',245)
s+=box(52,741,385,165,'Q与K只读语义特征',['中心 → WQ → K个query','原patch → WK → N个key','注意力分数是K×N矩阵','簇外加−∞后权重为0'],BLUE)+line(437,815,483,815)
s+=box(498,741,395,165,'V = WV(x + P)',['P先加到原patch特征','再通过WV改变通道维度','一般不等于WV(x) + P','位置在内容中，不直接加到Q/K'],ORANGE)+line(893,815,939,815)
