s+=box(53,705,375,177,'直方图匹配',['参考：[−3,−1,1,3]','当前：[.1,2,−1,.7]','rank赋值：[−1,3,−3,1]','值集合相同，位置不同'],ORANGE)
s+=box(484,705,390,177,'去均值 → FFT → 幅度校正',['保留当前相位，换回参考幅度','IFFT后加回该轮均值','频谱恢复，直方图可能再变化','K轮不是K张额外校准图'],GREEN)+line(428,782,477,782)
