s+=box(714,715,621,177,'aₜ=(1−t)ε+ta，监督速度1.2',['若预测1.0，该维平方误差.04','Euler每步dt=1/16，理想恒速每次+.075','从−.4累加16次 → .8','真实速度依赖状态；不是实测游戏轨迹'],GREEN)
