s+=box(53,700,610,172,'q=(1,1)，K={(2,0),(0,2)}',['逐维最大(2,2) → 上界4','两个真实成员分数均2，上界可以较松','U=q+ᵀmax(K)+q−ᵀmin(K)','簇内规约是必要步骤，不是自动出现'],GREEN)+box(714,700,621,172,'单维q=1，K={−2,−1}',['Quest上界−1；截K正部却得0','Algorithm2/3没展开完整簇摘要/索引使用','不能以等价一句替代kernel核查','只是阅读核对，未写入作者代码修补'],PURPLE)
