s+=box(714,425,621,175,'持久条约[1,√2)，不是固定b1=1',['b0也不总等于batch大小','坐标放大2倍，出生/死亡尺度同变','绝对持久阈值固定时计数可能变','示意非作者激活，不调用真实拓扑数据'],ORANGE)
