s+=box(53,705,610,133,'层A：10环/1000元素=.01',['层B：4环/100元素=.04 → B优先','20候选、ρ=.1 → 教学选2层','激活规模是成本代理，不是精确硬件成本'],GREEN)+box(714,705,621,133,'通道筛选不会自动把模型剪小',['默认主表选全部通道','冻结通道仍可能需要前向计算','梯度mask还要核查动量/权重衰减更新'],PURPLE)
s+=panel(895,'04  W1可训、W2冻结、W3可训：W1梯度仍需经过f2',285)
s+=box(53,955,610,177,'x → f1(W1) → f2(W2固定) → f3(W3)',['不求W2参数梯度，不等于切断输入梯度','整段no_grad可能让W1收不到训练信号','早层被选时，后部冻结仍有反向成本','BN运行统计与参数冻结要分别检查'],BLUE)+box(714,955,621,177,'选择缓存 / 拓扑 / 后训练分开计账',['40点距离矩阵1600项，400点160000项','还需高维激活与复杂形内存','环多是经验选择信号，不是任务相关性证明','未跑真实激活、训练或边缘设备实验'],ORANGE)
