# phi-DPO: fixed stage reference, focal gradient sign and conditional fairness.
s=panel(115,'01  当前阶段(x,y+,y−)；参考冻结，current以LoRA学习',225)
s+=box(53,175,610,133,'current两回答log概率差Δt',['序列log概率为回答token分数求和','reference两回答得到Δref，无梯度','s=β(Δt−Δref)，p=sigmoid(s)'],BLUE)+box(714,175,621,133,'教学Δref=1、Δt=2、β=.1',['s=.1，p≈.524979，DPO≈.644397','初始化current=reference时p=.5','p不是整任务准确率，也不是用户群体比例'],PURPLE)
s+=panel(365,'02  focal损失−(1−p)^γ ln p；困难度不等于少数群体身份',225)
s+=box(53,425,610,133,'γ=2，p=.9 → 损失≈.001054',['p=.1 → 损失≈1.865094','容易对被降权；困难对保留较强影响','γ=0退化普通DPO，不按群体频率直接反权重'],GREEN)+box(714,425,621,133,'正确链式梯度含权重自身导数',['dℓ/ds=(1−p)^γ[γp ln p−(1−p)]','p=.5、γ=2 → −.298287','下降增加正确偏好logit；勿detach focal权重'],BLUE)
s+=panel(615,'03  原文式15符号与式14求导不同：必须核代码，不照抄展开',255)
s+=box(53,675,610,177,'γ因子括号应为(1−p)−γp ln p',['印刷式15写加号；教学例会反转更新方向','本地有限差分仅核数学，不是作者代码验收','组内E[αg]一般不等于E[α]E[g]','组梯度因子分解还需协方差条件'],ORANGE)+box(714,675,621,177,'SFT答案NLL + focal偏好损失',['SFT学当前任务；reference在当前输入评分','结束阶段保存current，下阶段作新参考','不存在旧任务数据自动重放','完整冻结范围/缓存/权重参数待核验'],PURPLE)
s+=panel(895,'04  低DPO不无条件保证全策略KL小；γ过大也可能一起无梯度',285)
s+=box(53,955,610,176,'三回答教学：reference=(1/3,1/3,1/3)',['current=(1−2ε,ε,ε)，只观测首优于次','ε趋0：该对DPO趋0，但KL可增大','定理须保留覆盖/概率等附录条件','这是数学边界，不冒充独立审完所有证明'],ORANGE)+box(714,955,621,176,'公平/遗忘/适应分开评价',['困难度与少数主题不一定一致','梯度差归零也可能只是所有更新消失','两回答×两模型有前向/缓存成本','未调用LLM、训练LoRA或做模型实验'],GREEN)
