s+=box(53,175,610,133,'CvM：浅CNN → self/cross-view transformer',['128通道、1/8分辨率、6层注意力','窗口上下文不等于已知正确像素对应','主干与CvM空间对齐后才可拼通道'],BLUE)+box(714,175,621,133,'Fi + 深度代价体Ci + f(Ii) → 任务头',['逻辑融合Cm+L+128通道','分割/深度/法向/边界各有监督','视频额外帧只有深度标签，不伪造缺失任务'],PURPLE)
s+=panel(365,'02  教学f=100、基线b=.1、参考u=50；参考→邻图平移−b',255)
s+=box(53,425,610,176,'u′=u−fb/d',['d=1 → 邻图u′=40','d=2 → 邻图u′=45','同一参考像素，不同深度去不同位置匹配','相机方向反了，视差符号也会反'],BLUE)+box(714,425,621,176,'先逆内参回投影，再相对位姿，再投影',['Xi=d Ki⁻¹p；Xj=RjiXi+tji','pj∼KjXj，除Z后采样邻图特征','特征缩放时内参/主点也须匹配','插值/遮挡/越界规则原文未给全'],ORANGE)
