s+=box(53,705,610,133,'教学深度端点1和4，L=3',['逆深度[1,.625,.25] → d=[1,1.6,4]','K=2，参考(1,0)，匹配(1,0)/(0,1)','分数.7071/0：相似度大非概率已归一'],GREEN)+box(714,705,621,133,'480×640、L128教学',['特征60×80，C有614400项','float32约2.34MiB/视图，仅算最终C','中间warp特征、梯度与attention另计'],PURPLE)
s+=panel(895,'04  复制单图不产生真实双目；相同相机条件下深度轴会退化',285)
s+=box(53,955,610,176,'若Ki=Kj、R=I、t=0',['pj(d)∼K(dK⁻¹p)∼p，对所有d相同','两路特征相同则C沿d重复','重复图相机处理主文未给全，需实现核验','性能提升不证明得到新的视差观测'],ORANGE)+box(714,955,621,176,'任务loss联合学习，不凭空增加新一致性loss',['单图也可运行辅助结构与特征融合','相机误差/运动/遮挡仍会污染匹配','增加视图或深度候选不是必然提升','未训练模型、运行COLMAP或重建场景'],GREEN)
