# cryoDeRec: simulation provenance, shared two-pass gradients and Fourier ambiguity.
s=panel(115,'01  先训练噪声G；冻结后，同一密度生成配准输入/目标',225)
s+=box(53,175,610,133,'实验电影帧 → 运动校正P → 帧减P',['二维残差训练WGAN-GP；不是精确纯噪声','理想独立T=4：差分方差=.75σ²','平均投影噪声却为.25σ²，尺度须核验'],BLUE)+box(714,175,621,133,'ρ → 两条投影/WBP支路',['x：有限角 → CTF → 加G噪声 → WBP','y：全角、无CTF、无噪 → WBP','目标仍是离散重建近似，不是实测真值'],PURPLE)
s+=panel(365,'02  一个fθ，两次前向；不是两个恢复网络或两个任务头',255)
s+=box(53,425,610,176,'第一支 x → fθ(x)，目标y',['第二支 T_R(x) → FFT → ×M → IFFT → fθ','第二支目标为T_R(y)，目标不加mask','同一R保持空间配准；M作用在频域','原覆盖旋转后再相乘：M(k)W(R⁻¹k)'],GREEN)+box(714,425,621,176,'L = Lfidelity + .1 Lrecon',['两支梯度相加，只更新共享恢复θ','G已冻结，不反向训练成像数据生成','每块平方和或体素mean会改变梯度尺度','主文未给层通道、FFT网格或旋转采样细节'],ORANGE)
s+=panel(645,'03  8点DFT教学：删频率不能唯一还原；三维M是楔形频域mask',225)
s+=box(53,705,610,133,'x[n]=2+cos(2πn/8)',['DFT：DC=16，±1频率各4','仅留DC → IFFT后每一点都是2','抹去频率影响全部空间点，不是空间涂黑'],BLUE)+box(714,705,621,133,'常数2也变成相同输入',['两种原信号共享一个被遮蔽观测','恢复起伏依赖训练先验，不是测到新证据','学习补全必须防结构幻觉，ENL不能证真'],PURPLE)
s+=panel(895,'04  真实推理只WBP → 切块 → 冻结fθ → 拼接',285)
s+=box(53,955,610,176,'作者96³块、重叠32，内部步长64',['教学192³若末块贴边：0/64/96起点','每轴3块，共27块；末端重叠变64','作者padding/拼接权重未展开','不把任意教学拼接方案冒充原代码'],GREEN)+box(714,955,621,176,'B=4单份float32输入约13.5MiB',['同大小complex64频谱约27MiB','目标/双支激活/梯度/优化器另计','FFT约QlogQ，网络成本需层配置','未训练模型或恢复真实电镜体积'],ORANGE)
