s+=box(53,175,610,133,'ViT每层缓存K/V/attention输出/MLP',['P=8，复用率75% → 选2行重算','相似度[1,.99,.9,.8,.95,.4,−.2,.98]','从1计数选择第7/6，完整输出仍8行'],BLUE)+box(714,175,621,133,'k个Q读取P个K/V，不是k×k',['2×8分数 → softmax → 2行新输出','scatter到参考输出副本，静态行沿用','式4–6的K/V写法不自洽，完整策略待核'],ORANGE)
s+=panel(365,'02  先编码完整Z → 当前SCA / 过去TCA → 评分 → 才更新历史',225)
s+=box(53,425,610,133,'SCA=当前P个token均值',['TCA=至多W个过去帧均值的平均','旧H不含当前帧；评分完再append SCA','首帧空历史/零范数/α和W默认未展开'],GREEN)+box(714,425,621,133,'S=α(1−cos TCA)+(1−α)(1−cos SCA)',['按式8是加权和，非附近所称乘积','TopK后才缩短LLM视觉序列','更新缓存/锚点≠训练模型参数'],PURPLE)
s+=panel(615,'03  4 token二维教学：两锚点+余弦+排序可手算',255)
s+=box(53,675,610,176,'Z=[(1,0),(1,0),(0,1),(−1,0)]',['TCA=(1,0)，SCA=(.25,.25)，α=.5','分数≈[.146447,.146447,.646447,1.853553]','裁减50% → 选择第4/3行','投影与输入仍需保留原时间/空间位置'],BLUE)+box(714,675,621,176,'新颖只是代理，不保证未知问题有用',['常驻文字可能低分，罕见噪声可能高分','Cacher误差会改变Z、锚点和最终排名','实验单Pruner裁75%、联合裁70%','式后25%例子写反，切勿混淆保留/裁减'],ORANGE)
s+=panel(895,'04  两种缓存分开：ViT参考状态 ≠ 基底LLM的历史KV',285)
s+=box(53,955,610,176,'J4/重算.25：理想周期占比.4375',['仅选中重算部分，不含全Key/LN/索引','教学16帧×100token，留30% → 480','不是论文实际token配置','缓存带宽、文本历史、解码均另计'],GREEN)+box(714,955,621,176,'所有权重冻结，仅处理已到达帧',['非参考帧只降低部分ViT计算','Pruner主要降低LLM预填充成本','.3²=.09仅纯视觉二次项，非总时延','未运行模型或测量GPU加速'],PURPLE)
