# 4DSurf: normal component, depth derivative scope, segment transfer and incremental adapters.
s=panel(115,'01  每段G个二维高斯盘 + 时间运动场 → 变形盘 → 可微渲染',225)
s+=box(53,175,610,133,'canonical μ:G×3 / q:G×4 / ξ:G×2',['Fθ(μ,t) → v3 + ω3 + e2，共G×8','μt=μ+t v；qt=φ(tω)⊗q；ξt=ξ+t e','若v随t变，dμt/dt=v+t∂tv，不能当ODE'],BLUE)+box(714,175,621,133,'RGB / 深度 / 法向 / alpha共同参与优化',['光轴深度差D(p*)−d(μt)近似SDF','不是任意点精确欧氏距离或传感真值','偏导/移动采样/多相机口径待补充核验'],ORANGE)
s+=panel(365,'02  运输方程 ∂ts+∇s·u=0 → f=−u·n，约束只有法向分量',255)
s+=box(53,425,610,176,'教学平面s=z−a(t)，n=(0,0,1)',['u=(0,0,.2) → f=−.2','u=(1,0,.2) → f仍−.2','纯切向(1,0,0) → f=0，仍可在移动','旋转项ω×Rx需要同一坐标与旋转中心'],GREEN)+box(714,425,621,176,'运动flow与深度flow是同模型两种估计',['Lflow=Σ|f−ftilde|，不是双真值监督','教学−.2与−.1 → 该项残差.1','两侧可共同错误但一致，需图像等项','中心采样+局部刚性不保证整个盘任意形变'],PURPLE)
